pub fn count_lowercase(text: &str) -> usize {
    let mut n = 0;
    for c in text {
        if c.is_lowercase() {
            n += 1;
        }
    }
    n
}

pub fn run() -> usize {
    count_lowercase("Ferris The Crab")
}

exercises.tests:
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn counts_lowercase_letters() {
        assert_eq!(run(), 10);
        assert_eq!(count_lowercase("ABC"), 0);
        assert_eq!(count_lowercase(""), 0);
    }
}

exercises.solution:
pub fn count_lowercase(text: &str) -> usize {
    let mut n = 0;
    for c in text.chars() {
        if c.is_lowercase() {
            n += 1;
        }
    }
    n
}

pub fn run() -> usize {
    count_lowercase("Ferris The Crab")
}

