pub fn find(grid: &[[u8; 3]; 3], needle: u8) -> Option<(usize, usize)> {
    let mut found = None;
    for (r, row) in grid.iter().enumerate() {
        for (c, cell) in row.iter().enumerate() {
            if *cell == needle {
                found = Some((r, c));
                break 'search;
            }
        }
    }
    found
}

pub fn run() -> Option<(usize, usize)> {
    find(&[[1, 2, 3], [4, 5, 6], [7, 8, 9]], 6)
}

exercises.tests:
