pub fn advice(retries: i32) -> &'static str {
    match retries {
        n if n <= 0 => "give up",
        n if n < 3 => "retry now",
        n if n < 10 => "retry with backoff",
    }
}

pub fn run() -> (&'static str, &'static str) {
    (advice(2), advice(50))
}

exercises.tests:
