mod tests {
    use super::*;
    #[test]
    fn every_band() {
        assert_eq!(advice(0), "give up");
        assert_eq!(advice(-4), "give up");
        assert_eq!(advice(2), "retry now");
        assert_eq!(advice(5), "retry with backoff");
        assert_eq!(advice(50), "page someone");
    }
    #[test]
    fn run_pair() {
        assert_eq!(run(), ("retry now", "page someone"));
    }
}

